"""Read-only evidence synthesis. Does not train or modify frozen data/model artifacts."""
import collections,hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent;OUT=ROOT/'closure';ALL=ROOT.parent
ORIG=ALL/'is6400-research-questions-20261111/question-register.json'
V=ALL/'is6400-validation-20261111';C=ALL/'is6400-common-comparison-20261112';A=C/'ae-followup'
OK='限定范围已验证';WEAK='现有数据证据不足';LACK='数据或资料不具备不能验证';NO='明确不在当前必要范围且理由'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def evidence(*ps):
    out=[]
    for p in ps:
        p=Path(p);assert p.is_file(),p
        out.append(dict(path=str(p).replace('\\','/'),sha256=sha(p)))
    return out
def row(cat,done,conclusion,boundary,human,external,ps,**kw):
    return dict(closeout_class=cat,actually_completed=done,conclusion=conclusion,boundary=boundary,human_decision=human,missing_external_data_or_material=external,evidence=evidence(*ps),computational_debt_in_frozen_scope=False,**kw)
